// Climate control index — record JAH-GPC-THERMOSTAT-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"zones": 2, "sensors": 3, "price_usd": 200};
var value = (m.zones*m.sensors/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-THERMOSTAT-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-THERMOSTAT-000001|' + value.toFixed(2) + ' control index');

